contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public test entry.
    function run(address a1, address a2, address keepAddr, address requester, bytes32 digest, bytes32 r, bytes32 s, bytes32 pubX, bytes32 pubY, bytes32 txid, uint256 utxoSize, bytes memory redeemerOutputScript, uint256 requestedFee, bytes memory outpoint, bool wasFraud) public payable {
        // require non-zero addresses to make observations meaningful
        require(a1 != address(0) && a2 != address(0));

        // Record approval statuses before any state-changing calls
        bool before1 = c.approvedLoggers(a1); if (__ESBMC_reverted()) return;
        bool before2 = c.approvedLoggers(a2); if (__ESBMC_reverted()) return;

        // Call each logging function once from this contract (msg.sender == address(this))
        // Capture return via separate unique variables to avoid redeclaration issues.
        bool ok0;
        bool v0 = c.logCreated(keepAddr); bool __rev0 = __ESBMC_reverted(); if (__rev0) { ok0 = false; } else { ok0 = v0; }
        bool ok1;
        bool v1 = c.logRedemptionRequested(requester, digest, utxoSize, redeemerOutputScript, requestedFee, outpoint); bool __rev1 = __ESBMC_reverted(); if (__rev1) { ok1 = false; } else { ok1 = v1; }
        bool ok2;
        bool v2 = c.logGotRedemptionSignature(digest, r, s); bool __rev2 = __ESBMC_reverted(); if (__rev2) { ok2 = false; } else { ok2 = v2; }
        bool ok3;
        bool v3 = c.logRegisteredPubkey(pubX, pubY); bool __rev3 = __ESBMC_reverted(); if (__rev3) { ok3 = false; } else { ok3 = v3; }
        bool ok4;
        bool v4 = c.logSetupFailed(); bool __rev4 = __ESBMC_reverted(); if (__rev4) { ok4 = false; } else { ok4 = v4; }
        bool ok5;
        bool v5 = c.logFraudDuringSetup(); bool __rev5 = __ESBMC_reverted(); if (__rev5) { ok5 = false; } else { ok5 = v5; }
        bool ok6;
        bool v6 = c.logFunded(); bool __rev6 = __ESBMC_reverted(); if (__rev6) { ok6 = false; } else { ok6 = v6; }
        bool ok7;
        bool v7 = c.logCourtesyCalled(); bool __rev7 = __ESBMC_reverted(); if (__rev7) { ok7 = false; } else { ok7 = v7; }
        bool ok8;
        bool v8 = c.logStartedLiquidation(wasFraud); bool __rev8 = __ESBMC_reverted(); if (__rev8) { ok8 = false; } else { ok8 = v8; }
        bool ok9;
        bool v9 = c.logRedeemed(txid); bool __rev9 = __ESBMC_reverted(); if (__rev9) { ok9 = false; } else { ok9 = v9; }
        bool ok10;
        bool v10 = c.logLiquidated(); bool __rev10 = __ESBMC_reverted(); if (__rev10) { ok10 = false; } else { ok10 = v10; }
        bool ok11;
        bool v11 = c.logExitedCourtesyCall(); bool __rev11 = __ESBMC_reverted(); if (__rev11) { ok11 = false; } else { ok11 = v11; }

        // Read approval statuses after the calls
        bool after1 = c.approvedLoggers(a1); if (__ESBMC_reverted()) return;
        bool after2 = c.approvedLoggers(a2); if (__ESBMC_reverted()) return;

        // General rule: none of the logging calls changed the approvedLoggers entries for the observed addresses.
        assert(before1 == after1 && before2 == after2);
    }

    receive() external payable { }
}

